/**
 * The hits a search shows stay the same when its handler gets faster (c191): for a fixed fixture and a fixed set of searches, every hit, its
 * order, its snippet and the total match the answer the code gave before the p226 handler work. The fixture's clock is fixed, so `at`
 * and the date filters read the same on every run, and the DM posts are seeded with their delivery stopped, so no agent reply races a search.
 */
import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { after, before, test } from "node:test";
import type { SearchResult } from "../../web/src/lib/api/types.ts";
import { AgentStore } from "../../server/agent-store.ts";
import { seedFixture } from "../../server/fixture/seed.ts";
import { FixtureHost } from "../../server/host/fixture.ts";
import { start, type Running } from "./helpers.ts";

const NOW = Date.UTC(2026, 10, 20, 3);

let s: Running;
let dataDir: string;
before(async () => {
  dataDir = mkdtempSync(join(tmpdir(), "apps-chat-test-"));
  const host = new FixtureHost();
  host.wordMs = 0;
  seedFixture(host, dataDir, NOW);
  const store = new AgentStore(dataDir);
  const stopped = (at: number) => ({ target: "ag_vent", state: "stopped" as const, attempts: 1, at, requestId: `d:${at}` });
  const dm = store.append({ room: "dm_vent", author: "owner", text: "Is the relay up in the DM too? Notes at https://example.com/relay-notes", images: [], at: NOW - 3_600_000, requestId: "same-results-dm-1" }).post;
  store.set(dm, { delivery: stopped(NOW - 3_600_000) });
  const reply = store.append({ room: "dm_vent", author: "owner", text: "And the canary relay error from 02:10, did the restart clear it?", images: [], at: NOW - 3_000_000, requestId: "same-results-dm-2", threadRoot: dm.id }).post;
  store.set(reply, { delivery: stopped(NOW - 3_000_000) });
  s = await start({ host, dataDir });
  // Meilisearch's order, not the engine's merge of what it has not indexed yet, which the first search read while the posts were in flight.
  await s.app.searchEngine.settled();
});
after(async () => {
  await s.close();
  rmSync(dataDir, { recursive: true, force: true });
});

test("every search answers the same hits, in the same order, with the same snippets and totals", async () => {
  for (const [query, expected] of Object.entries(EXPECTED)) {
    const { nextCursor, ...answer } = await s.get<SearchResult>(`/api/search?${query}`);
    // A cursor is the next page's offset and the time the first page read up to (search.ts `readCursor`), which reads the run's clock.
    assert.deepEqual({ ...answer, ...(nextCursor ? { nextCursor: nextCursor.split(".")[0] } : {}) }, expected, query);
  }
});

